package com.dedhapp3n.pokeldn.frlg

/** Exact upstream install-resident noclip payloads generated for hold=0x100 (R). */
internal object WalkThroughWallsPayloads {
    private val payloads = mapOf(
        "BPRF" to "".hexBytesWtw(),
        "BPGF" to "".hexBytesWtw(),
        "BPRE" to "".hexBytesWtw(),
        "BPGE" to "".hexBytesWtw(),
        "BPRS" to "".hexBytesWtw(),
        "BPGS" to "".hexBytesWtw(),
        "BPRD" to "".hexBytesWtw(),
        "BPGD" to "".hexBytesWtw(),
        "BPRI" to "".hexBytesWtw(),
        "BPGI" to "".hexBytesWtw(),
        "BPRJ" to "".hexBytesWtw(),
        "BPGJ" to "".hexBytesWtw(),
    )

    fun forGameCode(code: String): ByteArray? = payloads[code]?.copyOf()
}

private fun String.hexBytesWtw() = chunked(2).map { it.toInt(16).toByte() }.toByteArray()
